examples.code:
tasks = {"인프라": (6, []), "미들웨어": (8, ["인프라"]), "ICS": (5, ["인프라"]),
         "ELIS": (4, ["미들웨어"]), "모니터링": (5, ["미들웨어", "ICS"]),
         "백업·DR": (3, ["인프라"]), "통합시험": (4, ["ELIS", "모니터링", "백업·DR"]),
         "운영전환": (2, ["통합시험"])}
ef = {}
def finish(t):
    if t not in ef:
        d, pre = tasks[t]
        ef[t] = d + max((finish(p) for p in pre), default=0)
    return ef[t]
end = max(finish(t) for t in tasks)
lf = {t: end for t in tasks}
for t in sorted(tasks, key=finish, reverse=True):
    for p in tasks[t][1]:
        lf[p] = min(lf[p], lf[t] - tasks[t][0])
print("전체 기간:", end, "주")   # 전체 기간: 25 주
for t in tasks:
    print(t, ef[t], lf[t] - ef[t])  # 미들웨어 14 0 / ICS 11 3 / 백업·DR 9 10 ...
